const e=[{number:1,type:"question",question:"ตามทฤษฎีอะตอมของโบร์ อิเล็กตรอนที่โคจรรอบนิวเคลียสในวงโคจรที่เสถียร (Stationary State) จะมีสมบัติอย่างไร",options:["แผ่คลื่นแม่เหล็กไฟฟ้าออกมาตลอดเวลา","มีโมเมนตัมเชิงมุมเป็นจำนวนเท่าของ \\ หรือ \\","มีพลังงานเพิ่มขึ้นเรื่อยๆ ตามระยะห่างจากนิวเคลียส","เคลื่อนที่ด้วยความเร่งเป็นศูนย์"],answer:"มีโมเมนตัมเชิงมุมเป็นจำนวนเท่าของ \\ หรือ \\",explanation:"โบร์เสนอว่าในวงโคจรที่เสถียร อิเล็กตรอนจะไม่แผ่รังสี และจะมีโมเมนตัมเชิงมุม (\\(L\\)) เป็นจำนวนเต็มเท่าของค่าคงตัวมูลฐาน คือ \\(L = n\\hbar = n\\frac{h}{2\\pi}\\)",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"10. อธิบายทฤษฎีอะตอมของโบร์ และการเกิดเส้นสเปกตรัม"}},{number:2,type:"question",question:"รัศมีวงโคจรของอิเล็กตรอนในอะตอมไฮโดรเจนตามแบบจำลองของโบร์ แปรผันตามเลขควอนตัมหลัก (\\(n\\)) อย่างไร",options:["แปรผันตรงกับ \\(n\\)","แปรผันตรงกับ \\(n^2\\)","แปรผกผันกับ \\(n\\)","แปรผกผันกับ \\(n^2\\)"],answer:"แปรผันตรงกับ \\(n^2\\)",explanation:"จากสูตร \\(r_n = n^2 r_1\\) รัศมีวงโคจรจะแปรผันตรงกับกำลังสองของเลขควอนตัมหลัก (\\(n^2\\))",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"10. อธิบายทฤษฎีอะตอมของโบร์ และการเกิดเส้นสเปกตรัม"}},{number:3,type:"fill-in-number",question:"พลังงานสถานะพื้น (Ground State, n=1) ของอะตอมไฮโดรเจนมีค่า -13.6 eV จงหาพลังงานของอิเล็กตรอนในระดับชั้น n=2 (ตอบเป็นทศนิยม 2 ตำแหน่งในหน่วย eV)",answer:-3.4,unit:"eV",decimalPlaces:2,hint:"ใช้สูตร \\(E_n = \\frac{E_1}{n^2}\\)",explanation:"\\(E_n = \\frac{-13.6}{n^2}\\) ดังนั้น \\(E_2 = \\frac{-13.6}{2^2} = \\frac{-13.6}{4} = -3.40\\) eV",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"10. อธิบายทฤษฎีอะตอมของโบร์ และการเกิดเส้นสเปกตรัม"}},{number:4,type:"question",question:"เส้นสเปกตรัมชุดใดของอะตอมไฮโดรเจนที่อยู่ในช่วงแสงที่ตามองเห็น (Visible Light)",options:["อนุกรมไลแมน (Lyman)","อนุกรมบัลเมอร์ (Balmer)","อนุกรมพาสเชน (Paschen)","อนุกรมแบรกเกต (Brackett)"],answer:"อนุกรมบัลเมอร์ (Balmer)",explanation:"อนุกรมบัลเมอร์เกิดจากการเปลี่ยนระดับพลังงานจากชั้นสูงกว่าลงมายังชั้น n=2 ซึ่งให้คลื่นแม่เหล็กไฟฟ้าในช่วงแสงขาว (Visible light)",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"10. อธิบายทฤษฎีอะตอมของโบร์ และการเกิดเส้นสเปกตรัม"}},{number:5,type:"fill-in-number",question:"อะตอมไฮโดรเจนเปลี่ยนระดับพลังงานจาก n=3 มายัง n=2 จะปล่อยโฟตอนที่มีพลังงานกี่ eV (กำหนด \\(E_1 = -13.6\\) eV) (ตอบเป็นทศนิยม 2 ตำแหน่ง)",answer:1.89,unit:"eV",decimalPlaces:2,hint:"\\(\\Delta E = E_3 - E_2\\)",explanation:"\\(E_3 = -13.6/9 = -1.51\\) eV, \\(E_2 = -13.6/4 = -3.40\\) eV. พลังงานที่ปล่อยออกมา \\(\\Delta E = E_3 - E_2 = -1.51 - (-3.40) = 1.89\\) eV",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"10. อธิบายทฤษฎีอะตอมของโบร์ และการเกิดเส้นสเปกตรัม"}},{number:6,type:"question",question:"ข้อใดกล่าวถูกต้องเกี่ยวกับการเกิดสเปกตรัมแบบต่อเนื่อง (Continuous Spectrum) และสเปกตรัมแบบเส้น (Line Spectrum)",options:["แก๊สร้อนความดันต่ำให้สเปกตรัมแบบต่อเนื่อง","ของแข็งร้อนหรือแก๊สความดันสูงให้สเปกตรัมแบบต่อเนื่อง","สเปกตรัมแบบเส้นเกิดจากวัตถุดำ","สเปกตรัมของดวงอาทิตย์เป็นสเปกตรัมแบบเส้นสว่างเท่านั้น"],answer:"ของแข็งร้อนหรือแก๊สความดันสูงให้สเปกตรัมแบบต่อเนื่อง",explanation:"วัตถุที่มีความหนาแน่นสูง (ของแข็ง, ของเหลว, แก๊สความดันสูง) เมื่อร้อนจะแผ่รังสีเป็นสเปกตรัมต่อเนื่อง ส่วนแก๊สร้อนความดันต่ำจะให้สเปกตรัมแบบเส้นสว่าง (Line Emission Spectrum)",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"10. อธิบายทฤษฎีอะตอมของโบร์ และการเกิดเส้นสเปกตรัม"}},{number:7,type:"fill-in-number",question:"ถ้าต้องการทำให้อะตอมไฮโดรเจนที่อยู่ในสถานะพื้น (n=1) แตกตัวเป็นไอออน (Ionization) ต้องใช้พลังงานอย่างน้อยที่สุดกี่ eV (ตอบเป็นทศนิยม 1 ตำแหน่ง)",answer:13.6,unit:"eV",decimalPlaces:1,hint:"พลังงานไอออไนเซชันคือพลังงานที่ทำให้อิเล็กตรอนหลุดออกจากอะตอม (ไปที่ \\(n=\\infty\\))",explanation:"พลังงานที่สถานะพื้นคือ -13.6 eV พลังงานที่ \\(n=\\infty\\) คือ 0 eV ดังนั้นต้องใช้พลังงาน \\(0 - (-13.6) = 13.6\\) eV",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"10. อธิบายทฤษฎีอะตอมของโบร์ และการเกิดเส้นสเปกตรัม"}},{number:8,type:"question",question:"การทดลองของฟรังก์และเฮิรตซ์ (Franck-Hertz Experiment) ให้ผลสรุปที่สำคัญเรื่องใด",options:["อิเล็กตรอนมีประจุไฟฟ้าลบ","อะตอมมีนิวเคลียสขนาดเล็กตรงกลาง","ระดับพลังงานของอะตอมมีค่าไม่ต่อเนื่อง","แสงมีสมบัติเป็นอนุภาค"],answer:"ระดับพลังงานของอะตอมมีค่าไม่ต่อเนื่อง",explanation:"การทดลองของฟรังก์และเฮิรตซ์แสดงให้เห็นว่าอะตอมจะดูดกลืนพลังงานจากอิเล็กตรอนที่มาชนได้เฉพาะบางค่าเท่านั้น ซึ่งสนับสนุนทฤษฎีของโบร์เรื่องระดับพลังงานที่ไม่ต่อเนื่อง",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"10. อธิบายทฤษฎีอะตอมของโบร์ และการเกิดเส้นสเปกตรัม"}},{type:"scenario",title:"สถานการณ์: การทดลองปรากฏการณ์โฟโตอิเล็กทริก",description:"ฉายแสงที่มีความถี่ \\(f\\) ตกกระทบผิวโลหะที่มีฟังก์ชันงาน \\(W\\) พบว่ามีอิเล็กตรอนหลุดออกมา",questions:[{number:9,type:"question",question:"ถ้าเพิ่มความเข้มแสง (Intensity) โดยที่ความถี่คงเดิม จะเกิดผลอย่างไร",options:["พลังงานจลน์สูงสุดของโฟโตอิเล็กตรอนเพิ่มขึ้น","จำนวนโฟโตอิเล็กตรอนที่หลุดออกมาเพิ่มขึ้น (กระแสโฟโตอิเล็กตรอนเพิ่มขึ้น)","ความต่างศักย์หยุดยั้งเพิ่มขึ้น","ฟังก์ชันงานของโลหะลดลง"],answer:"จำนวนโฟโตอิเล็กตรอนที่หลุดออกมาเพิ่มขึ้น (กระแสโฟโตอิเล็กตรอนเพิ่มขึ้น)",explanation:"ตามทฤษฎีควอนตัม การเพิ่มความเข้มแสงคือการเพิ่มจำนวนโฟตอน ทำให้จำนวนอิเล็กตรอนที่ถูกชนหลุดออกมาเพิ่มขึ้น แต่พลังงานของแต่ละโฟตอนเท่าเดิม",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"11. อธิบายปรากฏการณ์โฟโตอิเล็กทริก"}},{number:10,type:"question",question:"ถ้าเพิ่มความถี่ของแสง (\\(f\\)) โดยให้ความเข้มแสงคงที่ จะเกิดผลอย่างไร",options:["จำนวนโฟโตอิเล็กตรอนเพิ่มขึ้น","พลังงานจลน์สูงสุดของโฟโตอิเล็กตรอนเพิ่มขึ้น","ฟังก์ชันงานของโลหะเพิ่มขึ้น","ไม่มีการเปลี่ยนแปลงใดๆ"],answer:"พลังงานจลน์สูงสุดของโฟโตอิเล็กตรอนเพิ่มขึ้น",explanation:"จากสมการ \\(hf = W + E_{k,max}\\) เมื่อความถี่ (f) เพิ่มขึ้น พลังงานของโฟตอนเพิ่มขึ้น ทำให้พลังงานจลน์สูงสุด (\\(E_{k,max}\\)) ของอิเล็กตรอนเพิ่มขึ้น",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"11. อธิบายปรากฏการณ์โฟโตอิเล็กทริก"}}]},{number:11,type:"question",question:"ข้อใดคือความหมายของ 'ความถี่ขีดเริ่ม' (Threshold Frequency, \\(f_0\\))",options:["ความถี่สูงสุดที่ตามองเห็นได้","ความถี่ต่ำสุดของแสงที่ทำให้อิเล็กตรอนหลุดจากผิวโลหะได้","ความถี่ที่ทำให้อิเล็กตรอนมีความเร็วแสง","ความถี่ของแสงที่ทำให้อะตอมสั่นพ้อง"],answer:"ความถี่ต่ำสุดของแสงที่ทำให้อิเล็กตรอนหลุดจากผิวโลหะได้",explanation:"ความถี่ขีดเริ่มคือความถี่ที่โฟตอนมีพลังงานเท่ากับฟังก์ชันงาน (\\(hf_0 = W\\)) พอดี ทำให้อิเล็กตรอนหลุดออกมาได้โดยไม่มีพลังงานจลน์เหลือ",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"11. อธิบายปรากฏการณ์โฟโตอิเล็กทริก"}},{number:12,type:"fill-in-number",question:"โลหะชนิดหนึ่งมีฟังก์ชันงาน 2.0 eV ถ้าฉายแสงที่มีพลังงานโฟตอน 3.5 eV ตกกระทบ พลังงานจลน์สูงสุดของโฟโตอิเล็กตรอนจะเป็นกี่ eV (ตอบเป็นทศนิยม 1 ตำแหน่ง)",answer:1.5,unit:"eV",decimalPlaces:1,hint:"ใช้สมการ \\(E_{photon} = W + E_{k,max}\\)",explanation:"\\(E_{k,max} = hf - W = 3.5 - 2.0 = 1.5\\) eV",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"11. อธิบายปรากฏการณ์โฟโตอิเล็กทริก"}},{number:13,type:"fill-in-number",question:"ในการทดลองโฟโตอิเล็กทริก ถ้าต้องใช้ความต่างศักย์หยุดยั้ง 1.2 โวลต์ เพื่อหยุดอิเล็กตรอน พลังงานจลน์สูงสุดของอิเล็กตรอนมีค่ากี่ eV (ตอบเป็นทศนิยม 1 ตำแหน่ง)",answer:1.2,unit:"eV",decimalPlaces:1,hint:"\\(E_{k,max} = eV_s\\)",explanation:"พลังงานจลน์สูงสุดในหน่วย eV จะมีค่าตัวเลขเท่ากับความต่างศักย์หยุดยั้งในหน่วยโวลต์ ดังนั้น \\(E_{k,max} = 1.2\\) eV",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"11. อธิบายปรากฏการณ์โฟโตอิเล็กทริก"}},{number:14,type:"question",question:"กราฟความสัมพันธ์ระหว่างความต่างศักย์หยุดยั้ง (\\(V_s\\)) กับความถี่ของแสง (\\(f\\)) มีลักษณะเป็นอย่างไร",options:["เส้นตรงผ่านจุดกำเนิด","เส้นตรงที่มีจุดตัดแกนตั้งเป็นค่าลบ","เส้นโค้งพาราโบลา","เส้นตรงขนานกับแกนนอน"],answer:"เส้นตรงที่มีจุดตัดแกนตั้งเป็นค่าลบ",explanation:"จากสมการ \\(eV_s = hf - W \\Rightarrow V_s = (h/e)f - (W/e)\\) ซึ่งเป็นสมการเส้นตรง \\(y = mx + c\\) โดยมีความชัน \\(h/e\\) และจุดตัดแกนตั้ง \\(-W/e\\)",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"11. อธิบายปรากฏการณ์โฟโตอิเล็กทริก"}},{number:15,type:"fill-in-number",question:"แสงความยาวคลื่น 300 nm มีพลังงานโฟตอนกี่ eV (กำหนด \\(hc \\approx 1240\\) eV·nm) (ตอบเป็นทศนิยม 2 ตำแหน่ง)",answer:4.13,unit:"eV",decimalPlaces:2,hint:"ใช้สูตร \\(E = \\frac{hc}{\\lambda}\\)",explanation:"\\(E = \\frac{1240}{300} \\approx 4.13\\) eV",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"11. อธิบายปรากฏการณ์โฟโตอิเล็กทริก"}},{number:16,type:"question",question:"ปรากฏการณ์ใดที่สนับสนุนแนวคิดว่าแสงมีสมบัติเป็นอนุภาค (Particle Nature of Light)",options:["การแทรกสอด (Interference)","การเลี้ยวเบน (Diffraction)","ปรากฏการณ์โฟโตอิเล็กทริก (Photoelectric Effect)","การหักเห (Refraction)"],answer:"ปรากฏการณ์โฟโตอิเล็กทริก (Photoelectric Effect)",explanation:"การแทรกสอดและการเลี้ยวเบนแสดงสมบัติความเป็นคลื่น ส่วนปรากฏการณ์โฟโตอิเล็กทริกและปรากฏการณ์คอมป์ตันอธิบายได้ดีที่สุดด้วยแนวคิดที่ว่าแสงเป็นก้อนพลังงานหรืออนุภาค (โฟตอน)",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"11. อธิบายปรากฏการณ์โฟโตอิเล็กทริก"}},{number:17,type:"question",question:"สมมติฐานของเดอบรอยล์ (De Broglie Hypothesis) กล่าวว่าอย่างไร",options:["แสงเป็นได้ทั้งคลื่นและอนุภาค","สสารทุกชนิดที่มีโมเมนตัมจะมีสมบัติเป็นคลื่นควบคู่ไปด้วย","ตำแหน่งและโมเมนตัมของอนุภาคไม่สามารถวัดได้แม่นยำพร้อมกัน","พลังงานของอิเล็กตรอนในอะตอมมีค่าไม่ต่อเนื่อง"],answer:"สสารทุกชนิดที่มีโมเมนตัมจะมีสมบัติเป็นคลื่นควบคู่ไปด้วย",explanation:"เดอบรอยล์เสนอว่าอนุภาคสาร (Matter) เช่น อิเล็กตรอน ก็มีสมบัติความเป็นคลื่น โดยมีความยาวคลื่น \\(\\lambda = h/p\\)",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"12. อธิบายทวิภาวะของคลื่นและอนุภาค และความยาวคลื่นเดอบรอยล์"}},{number:18,type:"question",question:"ความยาวคลื่นเดอบรอยล์ (De Broglie Wavelength) ของอนุภาคขึ้นอยู่กับปริมาณใด",options:["ประจุไฟฟ้า","โมเมนตัม","สปิน","ความหนาแน่น"],answer:"โมเมนตัม",explanation:"จากสูตร \\(\\lambda = \\frac{h}{p}\\) ความยาวคลื่นเดอบรอยล์แปรผกผันกับโมเมนตัม (\\(p\\)) ของอนุภาค",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"12. อธิบายทวิภาวะของคลื่นและอนุภาค และความยาวคลื่นเดอบรอยล์"}},{number:19,type:"fill-in-number",question:"อิเล็กตรอนมวล \\(9.1 \\times 10^{-31}\\) kg เคลื่อนที่ด้วยความเร็ว \\(1 \\times 10^6\\) m/s จะมีความยาวคลื่นเดอบรอยล์กี่นาโนเมตร (กำหนด \\(h = 6.63 \\times 10^{-34}\\) J·s) (ตอบเป็นทศนิยม 2 ตำแหน่ง)",answer:.73,unit:"nm",decimalPlaces:2,hint:"ใช้สูตร \\(\\lambda = \\frac{h}{mv}\\) และระวังหน่วย",explanation:"\\(\\lambda = \\frac{6.63 \\times 10^{-34}}{(9.1 \\times 10^{-31})(1 \\times 10^6)} = \\frac{6.63}{9.1} \\times 10^{-9} \\approx 0.728 \\times 10^{-9}\\) m = 0.73 nm",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"12. อธิบายทวิภาวะของคลื่นและอนุภาค และความยาวคลื่นเดอบรอยล์"}},{number:20,type:"question",question:"หลักความไม่แน่นอนของไฮเซนเบิร์ก (Heisenberg Uncertainty Principle) กล่าวถึงความสัมพันธ์ระหว่างปริมาณคู่ใด",options:["พลังงานและมวล","ตำแหน่งและโมเมนตัม","ความเร็วและความเร่ง","ประจุและสนามแม่เหล็ก"],answer:"ตำแหน่งและโมเมนตัม",explanation:"หลักความไม่แน่นอนระบุว่าเราไม่สามารถวัดตำแหน่ง (\\(\\Delta x\\)) และโมเมนตัม (\\(\\Delta p\\)) ของอนุภาคให้แม่นยำพร้อมกันได้ (\\(\\Delta x \\Delta p \\ge \\hbar/2\\))",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"12. อธิบายทวิภาวะของคลื่นและอนุภาค และความยาวคลื่นเดอบรอยล์"}},{number:21,type:"question",question:"กล้องจุลทรรศน์อิเล็กตรอนมีกำลังขยายสูงกว่ากล้องจุลทรรศน์แบบแสงมาก เพราะเหตุใด",options:["อิเล็กตรอนเคลื่อนที่เร็วกว่าแสง","อิเล็กตรอนมีความยาวคลื่นเดอบรอยล์สั้นกว่าความยาวคลื่นแสงมาก","เลนส์แม่เหล็กมีคุณภาพดีกว่าเลนส์แก้ว","อิเล็กตรอนทะลุทะลวงวัตถุได้ดีกว่า"],answer:"อิเล็กตรอนมีความยาวคลื่นเดอบรอยล์สั้นกว่าความยาวคลื่นแสงมาก",explanation:"กำลังขยายและความละเอียดของภาพขึ้นอยู่กับความยาวคลื่นที่ใช้ ยิ่งความยาวคลื่นสั้นยิ่งเห็นรายละเอียดเล็กๆ ได้ดี อิเล็กตรอนที่ถูกเร่งด้วยความต่างศักย์สูงจะมีความยาวคลื่นสั้นมากเมื่อเทียบกับแสง",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"12. อธิบายทวิภาวะของคลื่นและอนุภาค และความยาวคลื่นเดอบรอยล์"}},{number:22,type:"question",question:"ถ้าโปรตอนและอิเล็กตรอนเคลื่อนที่ด้วยความเร็วเท่ากัน อนุภาคใดจะมีความยาวคลื่นเดอบรอยล์สั้นกว่า",options:["โปรตอน","อิเล็กตรอน","เท่ากัน","บอกไม่ได้"],answer:"โปรตอน",explanation:"จาก \\(\\lambda = h/mv\\) เมื่อ v เท่ากัน อนุภาคที่มีมวล (m) มากกว่าจะมีความยาวคลื่นสั้นกว่า โปรตอนมีมวลมากกว่าอิเล็กตรอนประมาณ 1836 เท่า จึงมีความยาวคลื่นสั้นกว่า",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"12. อธิบายทวิภาวะของคลื่นและอนุภาค และความยาวคลื่นเดอบรอยล์"}},{number:23,type:"question",question:"ปรากฏการณ์ใดที่ยืนยันสมบัติความเป็นคลื่นของอิเล็กตรอน",options:["การเลี้ยวเบนของอิเล็กตรอนผ่านผลึก (การทดลองของเดวิสสันและเจอร์เมอร์)","การเบี่ยงเบนในสนามแม่เหล็ก","การชนแบบยืดหยุ่นกับอะตอม","ปรากฏการณ์โฟโตอิเล็กทริก"],answer:"การเลี้ยวเบนของอิเล็กตรอนผ่านผลึก (การทดลองของเดวิสสันและเจอร์เมอร์)",explanation:"การเลี้ยวเบนเป็นสมบัติเฉพาะของคลื่น การที่อิเล็กตรอนแสดงลวดลายการเลี้ยวเบนเมื่อผ่านผลึกนิกเกิล เป็นหลักฐานสำคัญที่ยืนยันสมมติฐานของเดอบรอยล์",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"12. อธิบายทวิภาวะของคลื่นและอนุภาค และความยาวคลื่นเดอบรอยล์"}},{number:24,type:"fill-in-number",question:"โฟตอนตัวหนึ่งมีโมเมนตัม \\(1.0 \\times 10^{-27}\\) kg·m/s จะมีความยาวคลื่นกี่นาโนเมตร (กำหนด \\(h = 6.63 \\times 10^{-34}\\) J·s) (ตอบเป็นจำนวนเต็ม)",answer:663,unit:"nm",hint:"ใช้สูตร \\(p = h/\\lambda \\Rightarrow \\lambda = h/p\\)",explanation:"\\(\\lambda = \\frac{6.63 \\times 10^{-34}}{1.0 \\times 10^{-27}} = 6.63 \\times 10^{-7}\\) m = 663 nm",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"12. อธิบายทวิภาวะของคลื่นและอนุภาค และความยาวคลื่นเดอบรอยล์"}},{number:25,type:"question",question:"ในปรากฏการณ์คอมป์ตัน (Compton Effect) เมื่อโฟตอนชนกับอิเล็กตรอนแล้วกระเจิงออกไป ความยาวคลื่นของโฟตอนที่กระเจิงจะเป็นอย่างไร",options:["สั้นลง","ยาวขึ้น","เท่าเดิม","เป็นศูนย์"],answer:"ยาวขึ้น",explanation:"ในการชน โฟตอนถ่ายเทพลังงานบางส่วนให้อิเล็กตรอน ทำให้โฟตอนมีพลังงานลดลง (\\(E = hc/\\lambda\\)) เมื่อพลังงานลดลง ความยาวคลื่นจึงเพิ่มขึ้น",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"12. อธิบายทวิภาวะของคลื่นและอนุภาค และความยาวคลื่นเดอบรอยล์"}},{number:26,type:"fill-in-number",question:"ถ้าเร่งอิเล็กตรอนจากหยุดนิ่งด้วยความต่างศักย์ 100 โวลต์ พลังงานจลน์ของอิเล็กตรอนจะเป็นกี่ eV (ตอบเป็นจำนวนเต็ม)",answer:100,unit:"eV",hint:"พลังงานในหน่วย eV มีค่าตัวเลขเท่ากับความต่างศักย์ในหน่วยโวลต์",explanation:"\\(E_k = qV = e(100) = 100\\) eV",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"11. อธิบายปรากฏการณ์โฟโตอิเล็กทริก"}},{number:27,type:"question",question:"กลุ่มหมอกอิเล็กตรอน (Electron Cloud) ในแบบจำลองอะตอมแบบกลุ่มหมอก แทนความหมายของอะไร",options:["ตำแหน่งที่แน่นอนของอิเล็กตรอน","อาณาเขตที่อิเล็กตรอนเคลื่อนที่ด้วยความเร็วแสง","โอกาสที่จะพบอิเล็กตรอน ณ ตำแหน่งต่างๆ","ประจุไฟฟ้าที่กระจายตัวสม่ำเสมอ"],answer:"โอกาสที่จะพบอิเล็กตรอน ณ ตำแหน่งต่างๆ",explanation:"ตามกลศาสตร์ควอนตัม เราไม่สามารถระบุตำแหน่งที่แน่นอนของอิเล็กตรอนได้ กลุ่มหมอกแสดงถึงความหนาแน่นของความน่าจะเป็น (Probability Density) ในการพบอิเล็กตรอนรอบนิวเคลียส",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"12. อธิบายทวิภาวะของคลื่นและอนุภาค และความยาวคลื่นเดอบรอยล์"}},{number:28,type:"fill-in-number",question:"แสงความถี่ \\(6 \\times 10^{14}\\) Hz ตกกระทบโลหะที่มีความถี่ขีดเริ่ม \\(4 \\times 10^{14}\\) Hz ความต่างศักย์หยุดยั้งจะเป็นกี่โวลต์ (กำหนด \\(h = 4.14 \\times 10^{-15}\\) eV·s) (ตอบเป็นทศนิยม 2 ตำแหน่ง)",answer:.83,unit:"V",decimalPlaces:2,hint:"\\(eV_s = hf - hf_0\\)",explanation:"\\(eV_s = h(f - f_0) = (4.14 \\times 10^{-15})(6 - 4) \\times 10^{14} = (4.14)(2) \\times 10^{-1} = 0.828\\) eV. ดังนั้น \\(V_s = 0.828\\) V \\(\\approx 0.83\\) V",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"11. อธิบายปรากฏการณ์โฟโตอิเล็กทริก"}},{number:29,type:"question",question:"ข้อใดไม่ใช่สมบัติของโฟตอน",options:["เคลื่อนที่ด้วยความเร็วแสงในสุญญากาศ","มีมวลขณะหยุดนิ่งเป็นศูนย์","มีประจุไฟฟ้า","มีพลังงานแปรผันตรงกับความถี่"],answer:"มีประจุไฟฟ้า",explanation:"โฟตอนเป็นอนุภาคของแสงที่เป็นกลางทางไฟฟ้า (ไม่มีประจุ) แต่มีพลังงานและโมเมนตัม",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"11. อธิบายปรากฏการณ์โฟโตอิเล็กทริก"}},{number:30,type:"fill-in-number",question:"อะตอมไฮโดรเจนในสถานะถูกกระตุ้นที่ n=4 จะสามารถปล่อยเส้นสเปกตรัมออกมาได้ทั้งหมดกี่เส้นเมื่อกลับสู่สถานะพื้น (ตอบเป็นจำนวนเต็ม)",answer:6,unit:"เส้น",hint:"จำนวนเส้นสเปกตรัมที่เป็นไปได้ = \\(\\frac{n(n-1)}{2}\\)",explanation:"จำนวนเส้น = \\(\\frac{4(4-1)}{2} = \\frac{12}{2} = 6\\) เส้น (ได้แก่ 4->3, 4->2, 4->1, 3->2, 3->1, 2->1)",subCategory:{main:"บทที่ 18: ฟิสิกส์อะตอม",specific:"10. อธิบายทฤษฎีอะตอมของโบร์ และการเกิดเส้นสเปกตรัม"}}];export{e as quizItems};
